/// <summary>
/// PricingAttribute of table <c>CustTable</c> field MainContactWorker.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableMainContactWorker extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, MainContactWorker);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Int64);
    CustTable   custTable;

    while select MainContactWorker from custTable
        group by MainContactWorker
    {
        ret.add(custTable.MainContactWorker);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, MainContactWorker));
    qbr.value(queryValue(_value));
}
